#!/usr/bin/env python3
"""Self-extracting Signal Desk source handoff (no git credentials needed).
Run in an empty or target repo checkout:
  python3 scripts/extract_signal_desk.py
Then commit and push from a repo-linked agent.
"""
from __future__ import annotations
import base64, io, tarfile
from pathlib import Path

B64 = """"""

def main() -> None:
    root = Path.cwd()
    data = base64.b64decode(B64)
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tar:
        tar.extractall(path=root)
    print(f"Extracted Signal Desk sources into {root}")
    print("Next: git checkout -b cursor/multi-horizon-platform-9c6f && git add -A && git commit && git push")

if __name__ == "__main__":
    main()
